const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Mock Source/Lease matching the interface in src/source.ts. Records every
// open()/read()/close() call and can inject failures. A read failure (if any)
// is raised on the first read that finds the value queue empty (the read that
// would have established exhaustion).
function makeSource(opts = {}) {
  const values = opts.values ? opts.values.slice() : [];
  const state = { opens: 0, reads: 0, closes: 0 };
  const source = {
    open: async () => {
      state.opens++;
      if (opts.openError) throw opts.openError;
      return {
        read: async () => {
          state.reads++;
          if (opts.readError && values.length === 0) throw opts.readError;
          const value = values.shift();
          return value === undefined ? null : value;
        },
        close: async () => {
          state.closes++;
          if (opts.closeError) throw opts.closeError;
        },
      };
    },
  };
  return { source, state };
}

async function rejects(fn, expectedError) {
  await assert.rejects(fn, (err) => err === expectedError);
}

async function main() {
  // 1. Normal exhaustion: mapped order, one open, one read per next plus the
  //    exhaustion read, closed exactly once; no read-ahead while suspended.
  {
    const { source, state } = makeSource({ values: ['a', 'b', null] });
    const it = new EventService(source).stream();
    assert.equal(state.opens, 0, 'no lease opened before first iteration');
    assert.deepEqual(await it.next(), { value: 'A', done: false });
    assert.equal(state.opens, 1, 'lease opened on first next');
    assert.equal(state.reads, 1);
    assert.deepEqual(await it.next(), { value: 'B', done: false });
    assert.equal(state.reads, 2, 'no read-ahead while suspended at yield');
    assert.deepEqual(await it.next(), { value: undefined, done: true });
    assert.equal(state.reads, 3, 'exactly one exhaustion read');
    assert.equal(state.closes, 1, 'closed exactly once on exhaustion');
    await it.return(); // late return after completion must not close again
    assert.equal(state.closes, 1, 'no double close after completion');
  }

  // 2. for-await sees records in order.
  {
    const { source, state } = makeSource({ values: ['a', 'b', 'c', null] });
    const found = [];
    for await (const value of new EventService(source).stream()) found.push(value);
    assert.deepEqual(found, ['A', 'B', 'C']);
    assert.equal(state.closes, 1);
  }

  // 3. Consumer break: close exactly once and no read-ahead after the break.
  {
    const { source, state } = makeSource({ values: ['a', 'b', null] });
    const found = [];
    for await (const value of new EventService(source).stream()) {
      found.push(value);
      break;
    }
    assert.deepEqual(found, ['A']);
    assert.equal(state.reads, 1, 'no read consumed after break');
    assert.equal(state.closes, 1, 'closed exactly once on break');
  }

  // 4. Consumer return() on a suspended generator closes exactly once.
  {
    const { source, state } = makeSource({ values: ['a', null] });
    const it = new EventService(source).stream();
    await it.next();
    assert.deepEqual(await it.return(), { value: undefined, done: true });
    assert.equal(state.closes, 1);
  }

  // 5. Returning an unopened generator must not open or close anything.
  {
    const { source, state } = makeSource({ values: ['a', null] });
    const it = new EventService(source).stream();
    assert.deepEqual(await it.return(), { value: undefined, done: true });
    assert.equal(state.opens, 0);
    assert.equal(state.reads, 0);
    assert.equal(state.closes, 0);
  }

  // 6. Source read failure: closed exactly once, original exception propagated.
  {
    const readError = new Error('read blew up');
    const { source, state } = makeSource({ readError });
    await rejects(async () => {
      for await (const value of new EventService(source).stream()) void value;
    }, readError);
    assert.equal(state.closes, 1);
  }

  // 7. Read failure on a later read, with close also failing:
  //    original exception preserved, close still attempted exactly once.
  {
    const readError = new Error('read blew up');
    const closeError = new Error('close blew up');
    const { source, state } = makeSource({ values: ['a'], readError, closeError });
    const it = new EventService(source).stream();
    assert.equal((await it.next()).value, 'A');
    await rejects(() => it.next(), readError);
    assert.equal(state.closes, 1);
  }

  // 8. Mapper failure: closed exactly once, mapper exception propagated.
  {
    const mapperError = new Error('mapper blew up');
    const { source, state } = makeSource({ values: ['a'] });
    await rejects(async () => {
      for await (const value of new EventService(source, () => { throw mapperError; }).stream()) void value;
    }, mapperError);
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // 9. Mapper failure with close also failing: original exception preserved.
  {
    const mapperError = new Error('mapper blew up');
    const closeError = new Error('close blew up');
    const { source, state } = makeSource({ values: ['a'], closeError });
    const it = new EventService(source, () => { throw mapperError; }).stream();
    await rejects(() => it.next(), mapperError);
    assert.equal(state.closes, 1);
  }

  // 10. Consumer-injected throw: closed exactly once, injected exception propagated,
  //     also preserved when close fails.
  {
    const injected = new Error('injected');
    const closeError = new Error('close blew up');
    for (const opts of [{}, { closeError }]) {
      const { source, state } = makeSource({ values: ['a', 'b'], ...opts });
      const it = new EventService(source).stream();
      assert.equal((await it.next()).value, 'A');
      await rejects(() => it.throw(injected), injected);
      assert.equal(state.closes, 1, 'closed exactly once on injected throw');
    }
  }

  // 11. Close failure on normal exhaustion is propagated.
  {
    const closeError = new Error('close blew up');
    const { source, state } = makeSource({ values: ['a', null], closeError });
    await rejects(async () => {
      for await (const value of new EventService(source).stream()) void value;
    }, closeError);
    assert.equal(state.closes, 1);
  }

  // 12. Close failure on consumer break is propagated out of the loop.
  {
    const closeError = new Error('close blew up');
    const { source, state } = makeSource({ values: ['a', null], closeError });
    await rejects(async () => {
      for await (const value of new EventService(source).stream()) {
        void value;
        break;
      }
    }, closeError);
    assert.equal(state.closes, 1);
  }

  // 13. Open failure: nothing to close, error propagated on first iteration.
  {
    const openError = new Error('open blew up');
    const { source, state } = makeSource({ openError });
    const it = new EventService(source).stream();
    await rejects(() => it.next(), openError);
    assert.equal(state.closes, 0);
  }

  // 14. return() racing an in-flight next(): the pending next still receives its
  //     value and the lease is still closed exactly once.
  {
    const { source, state } = makeSource({ values: ['a', null] });
    const it = new EventService(source).stream();
    const pendingNext = it.next();
    const pendingReturn = it.return();
    assert.deepEqual(await pendingNext, { value: 'A', done: false });
    assert.deepEqual(await pendingReturn, { value: undefined, done: true });
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  console.log('checks/service.cjs: all scenarios passed');
}

module.exports = main();

