import { Lease, Source } from './source';
import { mapEvent } from './mapper';

export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}
  /**
   * Yields mapped records in source order.
   *
   * Guarantees:
   * - The lease is opened lazily: nothing happens until the first `next()`.
   * - No read-ahead: exactly one read per resumption; the only extra read is the
   *   one that observes exhaustion (`null`).
   * - An opened lease is closed exactly once, regardless of how the stream ends:
   *   normal exhaustion, consumer break/return, source read failure, mapper
   *   failure or a consumer-injected throw (via `throw()`), including when the
   *   `return()` arrives while another request is still in flight.
   * - If `close()` fails while an exception is already propagating out of the
   *   body (read, mapper or consumer-injected), the original exception is
   *   preserved and the close failure is discarded; otherwise the close failure
   *   itself is propagated.
   */
  async *stream(): AsyncGenerator<string> {
    let lease: Lease | undefined;
    // True while an exception from the body (read, mapper or consumer-injected)
    // is propagating outward; a failing close must not replace it.
    let propagating = false;
    try {
      lease = await this.source.open();
      for (;;) {
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      propagating = true;
      throw error;
    } finally {
      const openLease = lease;
      lease = undefined;
      if (openLease !== undefined) {
        try {
          await openLease.close();
        } catch (closeError) {
          if (!propagating) throw closeError;
        }
      }
    }
  }
}
